<script setup lang="ts">
import { computed,reactive,ref } from "vue"; import {useRoute,useRouter} from "vue-router";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import Tabs from "@/components/zs/Tabs.vue"; import ActivityTimeline from "@/components/crm/ActivityTimeline.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import ScoreBadge from "@/components/crm/ScoreBadge.vue"; import ZButton from "@/components/zs/ZButton.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue";
import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData,useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import {showToast} from "@/composables/useToast"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("Company Profile","CRM company relationship workspace.");const route=useRoute(),router=useRouter(),data=useCrmData(),id=computed(()=>String(route.params.id)),state=useAsyncData(()=>crmRepository.company(data.activeCompanyId.value,id.value),{watch:[data.activeCompanyId,id]}),item=computed(()=>state.data.value),tab=ref("Overview"),activityOpen=ref(false),handoffOpen=ref(false);const contacts=computed(()=>(data.contacts.data.value??[]).filter((entry)=>entry.accountId===id.value)),leads=computed(()=>(data.leads.data.value??[]).filter((entry)=>entry.accountId===id.value)),deals=computed(()=>(data.deals.data.value??[]).filter((entry)=>entry.accountId===id.value)),activities=computed(()=>(data.activities.data.value??[]).filter((entry)=>entry.accountId===id.value));
const activity=reactive({type:"CALL",subject:"",description:"",due_at:"",priority:"MEDIUM"});const activityMutation=useMutation(()=>crmRepository.createActivity(data.activeCompanyId.value,{...activity,related_type:"account",related_id:id.value,status:"PENDING"}));async function logActivity(){const saved=await activityMutation.run();if(!saved)return;activityOpen.value=false;await data.activities.refresh();showToast("Activity saved",saved.subject,"success");}
const matches=useAsyncData(()=>crmRepository.customerMatches(data.activeCompanyId.value,id.value),{watch:[data.activeCompanyId,id],immediate:false});const handoff=reactive({customer_id:"",name:"",email:"",phone:"",ntn:"",cnic:"",address:"",city:"",country:"PK",currency:"PKR",type:"BUSINESS",is_active:true});const handoffMutation=useMutation(()=>crmRepository.handoffAccount(data.activeCompanyId.value,id.value,{...handoff,customer_id:handoff.customer_id||null}));function prepareHandoff(){Object.assign(handoff,{customer_id:"",name:item.value?.name??"",email:item.value?.email??"",phone:item.value?.phone??"",ntn:item.value?.ntn??"",cnic:item.value?.cnic??"",address:item.value?.address??"",city:item.value?.city??"",country:item.value?.country??"PK",currency:"PKR",type:item.value?.accountType==="INDIVIDUAL"?"INDIVIDUAL":"BUSINESS",is_active:true});handoffOpen.value=true;void matches.refresh();}async function handoffCustomer(){const customer=await handoffMutation.run();if(!customer)return;handoffOpen.value=false;await Promise.all([state.refresh(),data.companies.refresh()]);showToast("Customer handoff complete",`${customer.name} is linked to accounting.`,"success");}
</script>
<template><AppShell><AsyncSection :loading="state.loading.value" :error="state.error.value" @retry="state.refresh"><template v-if="item"><PageHeader :title="item.name" :description="`${item.industry||'CRM account'} · ${item.city||item.country||''}`"><template #actions><StatusBadge :status="item.status"/><ZButton variant="outline" @click="activityOpen=true">Log activity</ZButton><ZButton v-if="!item.customerId" @click="prepareHandoff">Create customer</ZButton><StatusBadge v-else status="Customer linked"/></template></PageHeader><Panel><Tabs v-model="tab" :items="['Overview','Contacts','Leads / Deals','Activities','Notes']"/><div v-if="tab==='Overview'" class="grid gap-6 p-5 lg:grid-cols-3"><dl class="grid gap-4 text-xs lg:col-span-2 sm:grid-cols-2"><div v-for="[key,value] in Object.entries({Website:item.website,Industry:item.industry,Phone:item.phone,Email:item.email,Address:item.address,Owner:item.owner||'Unassigned',Source:item.source,NTN:item.ntn||'—',CNIC:item.cnic||'—'})" :key="key"><dt class="label-caps">{{key}}</dt><dd class="mt-1 text-content">{{value}}</dd></div></dl><div class="rounded-md bg-surface-sunken p-4"><p class="label-caps">Relationship</p><p class="mt-3 text-sm font-semibold text-content">{{contacts.length}} contacts</p><p class="mt-1 text-sm font-semibold text-content">{{leads.length}} leads</p><p class="mt-1 text-sm font-semibold text-content">{{deals.length}} deals</p><p class="mt-1 text-xs text-content-muted">Last activity {{item.lastActivity||'—'}}</p></div></div><div v-else-if="tab==='Contacts'" class="divide-y divide-line px-4"><button v-for="contact in contacts" :key="contact.id" class="block w-full py-3 text-left" @click="router.push(`/crm/contacts/${contact.id}`)"><p class="text-sm font-medium text-content">{{contact.name}}</p><p class="text-xs text-content-muted">{{contact.title}} · {{contact.email}}</p></button></div><div v-else-if="tab==='Leads / Deals'" class="divide-y divide-line px-4"><button v-for="lead in leads" :key="lead.id" class="flex w-full items-center justify-between py-3 text-left" @click="router.push(`/crm/leads/${lead.id}`)"><div><p class="text-sm font-medium text-content">{{lead.name}}</p><p class="text-xs text-content-muted">{{lead.status}} · {{lead.owner}}</p></div><ScoreBadge :score="lead.score.total"/></button><button v-for="deal in deals" :key="deal.id" class="block w-full py-3 text-left" @click="router.push(`/crm/deals/${deal.id}`)"><p class="text-sm font-medium text-content">{{deal.name}}</p><p class="text-xs text-content-muted">{{deal.stage}} · {{deal.status}}</p></button></div><div v-else-if="tab==='Activities'" class="p-4"><ActivityTimeline :items="activities"/></div><div v-else class="p-5 text-sm text-content-secondary">{{item.notes||'No notes recorded.'}}</div></Panel></template></AsyncSection><SidePanel :open="activityOpen" title="Log account activity" @close="activityOpen=false"><form class="grid gap-4" @submit.prevent="logActivity"><label><span class="label-caps">Type</span><select v-model="activity.type" class="field mt-1.5"><option>CALL</option><option>MEETING</option><option>EMAIL</option><option>TASK</option><option>NOTE</option></select></label><Field v-model="activity.subject" label="Subject" required/><Field v-model="activity.due_at" label="Due at" type="datetime-local"/><label><span class="label-caps">Description</span><textarea v-model="activity.description" class="field mt-1.5 min-h-20"/></label><ValidationMessage :message="activityMutation.error.value?.message"/><ZButton type="submit">Save activity</ZButton></form></SidePanel><SidePanel :open="handoffOpen" title="Customer handoff" description="Link a matching Stage 3 customer or create one explicitly." @close="handoffOpen=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="handoffCustomer"><label class="sm:col-span-2"><span class="label-caps">Existing match</span><select v-model="handoff.customer_id" class="field mt-1.5"><option value="">Create a new customer</option><option v-for="customer in matches.data.value??[]" :key="customer.id" :value="customer.id">{{customer.name}} · {{customer.email}}</option></select></label><template v-if="!handoff.customer_id"><Field v-model="handoff.name" label="Customer name" required/><Field v-model="handoff.email" label="Email" type="email"/><Field v-model="handoff.phone" label="Phone"/><Field v-model="handoff.ntn" label="NTN"/><Field v-model="handoff.cnic" label="CNIC"/><Field v-model="handoff.city" label="City"/><label class="sm:col-span-2"><span class="label-caps">Address</span><textarea v-model="handoff.address" class="field mt-1.5 min-h-20"/></label></template><ValidationMessage class="sm:col-span-2" :message="handoffMutation.error.value?.message"/><ZButton class="sm:col-span-2" type="submit" :disabled="handoffMutation.saving.value">Complete handoff</ZButton></form></SidePanel></AppShell></template>
